#!/usr/bin/env bash
# Translation catalog maintenance for ImSlim.
#
# Extracts every string wrapped in `_()` into a gettext template, keeps the
# per-language catalogs in sync with it, and compiles them to the `.mo` files
# loaded at runtime (src/imslim/_i18n.py).
#
# Layout, all under src/imslim/locale/:
#   imslim.pot                        extracted template (regenerated by `extract`)
#   <lang>/LC_MESSAGES/imslim.po      translator-edited catalog (committed)
#   <lang>/LC_MESSAGES/imslim.mo      compiled catalog (committed, loaded at runtime)
#
# Run from the repository root:
#   ./scripts/translations.sh extract     # regenerate imslim.pot
#   ./scripts/translations.sh init fr     # start a new language
#   ./scripts/translations.sh update      # merge the template into every .po
#   ./scripts/translations.sh compile     # .po -> .mo
#   ./scripts/translations.sh all         # extract + update + compile
#
# Requires GNU gettext (xgettext, msginit, msgmerge, msgfmt).

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PACKAGE_DIR="$ROOT/src/imslim"
LOCALE_DIR="$PACKAGE_DIR/locale"
DOMAIN="imslim"
POT="$LOCALE_DIR/$DOMAIN.pot"

die() {
	printf 'translations: %s\n' "$*" >&2
	exit 1
}

require() {
	local tool
	for tool in "$@"; do
		command -v "$tool" >/dev/null 2>&1 || die "missing $tool (install GNU gettext)"
	done
}

po_files() {
	find "$LOCALE_DIR" -mindepth 3 -maxdepth 3 -name "$DOMAIN.po" 2>/dev/null | sort
}

extract() {
	require xgettext
	mkdir -p "$LOCALE_DIR"
	local version
	version="$(sed -n 's/^version = "\(.*\)"/\1/p' "$ROOT/pyproject.toml" | head -n 1)"
	local -a sources
	mapfile -t sources < <(cd "$ROOT" && find src/imslim -name '*.py' -not -path '*/locale/*' | sort)
	(
		cd "$ROOT"
		xgettext \
			--language=Python \
			--keyword=_ \
			--from-code=UTF-8 \
			--package-name=imslim \
			--package-version="$version" \
			--output="$POT" \
			"${sources[@]}"
	)
	printf 'extracted %s\n' "${POT#"$ROOT"/}"
}

init() {
	local lang="${1:-}"
	[ -n "$lang" ] || die "usage: translations.sh init <lang>"
	require msginit
	[ -f "$POT" ] || extract
	local dir="$LOCALE_DIR/$lang/LC_MESSAGES"
	if [ -e "$dir/$DOMAIN.po" ]; then
		die "$dir/$DOMAIN.po already exists"
	fi
	mkdir -p "$dir"
	msginit --input="$POT" --locale="$lang" --output-file="$dir/$DOMAIN.po" --no-translator
	printf 'created %s\n' "${dir#"$ROOT"/}/$DOMAIN.po"
}

update() {
	require msgmerge
	[ -f "$POT" ] || die "no $POT; run extract first"
	local po
	while IFS= read -r po; do
		msgmerge --update --backup=none --quiet "$po" "$POT"
	done < <(po_files)
}

compile_catalogs() {
	require msgfmt
	local po mo
	while IFS= read -r po; do
		mo="${po%.po}.mo"
		msgfmt --check --output-file="$mo" "$po"
		printf 'compiled %s\n' "${mo#"$ROOT"/}"
	done < <(po_files)
}

case "${1:-all}" in
extract) extract ;;
init)
	shift
	init "$@"
	;;
update) update ;;
compile) compile_catalogs ;;
all)
	extract
	update
	compile_catalogs
	;;
*) die "unknown command: $1 (extract | init | update | compile | all)" ;;
esac
